skin.css:
:root {
  --tb-glass: rgba(18, 18, 20, 0.62);
  --tb-glass-hi: rgba(255, 255, 255, 0.10);
  --tb-line: rgba(255, 255, 255, 0.16);
  --tb-text: #ffffff;
  --tb-muted: rgba(255, 255, 255, 0.72);
  --tb-accent: #e7b46a;
  --tb-accent-ink: #1b1408;
  --tb-radius: 999px;
  --tb-font: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
}

.tour-skin { font-family: var(--tb-font); color: var(--tb-text); }

.tb-bar {
  position: absolute;
  left: 50%;
  bottom: max(20px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: calc(100vw - 32px);
  padding: 8px;
  background: var(--tb-glass);
  border: 1px solid var(--tb-line);
  border-radius: var(--tb-radius);
  backdrop-filter: blur(14px) saturate(1.2);
  -webkit-backdrop-filter: blur(14px) saturate(1.2);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  pointer-events: auto;
}

.tb-btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 56px;
  padding: 0 22px;
  border: 0;
  border-radius: var(--tb-radius);
  background: var(--tb-glass-hi);
  color: var(--tb-text);
  font: 600 18px/1 var(--tb-font);
  cursor: pointer;
  white-space: nowrap;
  transition: background .15s, transform .1s;
}
.tb-btn:hover { background: rgba(255, 255, 255, 0.2); }
.tb-btn:active { transform: scale(.97); }
.tb-btn:focus-visible { outline: 3px solid var(--tb-accent); outline-offset: 2px; }
.tb-btn svg { width: 22px; height: 22px; flex: none; }

@media (max-width: 640px) {
  .tb-bar { bottom: 16px; gap: 6px; padding: 6px; }
  .tb-btn { min-height: 52px; padding: 0 16px; font-size: 16px; }
  .tb-btn .tb-label { display: none; }
}

.tb-crumbs { display: flex; align-items: center; gap: 4px; min-width: 0; overflow: hidden; }
.tb-crumb {
  display: inline-flex; align-items: center; gap: 8px;
  min-height: 48px; padding: 0 16px;
  border-radius: 999px;
  color: var(--tb-muted); text-decoration: none;
  font: 500 16px/1 var(--tb-font); white-space: nowrap;
  transition: background .15s, color .15s;
}
.tb-crumb:hover { color: var(--tb-text); background: rgba(255, 255, 255, 0.08); }
.tb-dot { width: 10px; height: 10px; border-radius: 50%; border: 2px solid currentColor; flex: none; }
.tb-crumb[data-tour-current] { background: var(--tb-accent); color: var(--tb-accent-ink); font-weight: 700; }
.tb-crumb[data-tour-current] .tb-dot { background: currentColor; }
@media (max-width: 900px) {
  .tb-crumb { padding: 0 12px; }
  .tb-crumb .tb-crumb-name { display: none; }
  .tb-crumb[data-tour-current] .tb-crumb-name { display: inline; }
}
@media (max-width: 640px) {
  .tb-crumb { min-height: 44px; padding: 0 10px; font-size: 15px; }
}
